#!/usr/bin/env bash
set -euo pipefail
source "$(dirname -- "${BASH_SOURCE[0]}")/../lib/common.sh"

N="${1:-27}"
if (( $# > 0 )); then shift; fi
[[ "$N" == 27 ]] || { echo 'profiled staged selector targets n=27' >&2; exit 2; }
PROFILE_FILE="${PROFILE_FILE:-$ONEESAN_ROOT/work/b300_hbm_profile_refined21.env}"
FORCED_PROFILE_FILE="${FORCED_PROFILE_FILE:-$ONEESAN_ROOT/work/b300_forced_profile_tune27.env}"
TUNE_FORCED="${TUNE_FORCED:-1}"; REBUILD_FORCED="${REBUILD_FORCED:-${REBUILD:-1}}"; REBUILD_BUCKETS="${REBUILD_BUCKETS:-${REBUILD:-1}}"
for x in TUNE_FORCED REBUILD_FORCED REBUILD_BUCKETS; do v="${!x}"; [[ "$v" == 0 || "$v" == 1 ]] || exit 2; done
[[ -f "$PROFILE_FILE" ]] || { echo "missing n21 profile: $PROFILE_FILE" >&2; exit 2; }
if [[ "$TUNE_FORCED" == 1 || ! -f "$FORCED_PROFILE_FILE" ]]; then PROFILE_OUT="$FORCED_PROFILE_FILE" PREFIX="${FORCED_TUNE_PREFIX:-$ONEESAN_ROOT/work/b300_forced_profile_tune27}" REBUILD="$REBUILD_FORCED" bash "$ONEESAN_ROOT/scripts/bench/b300-forced-profile-tune27.sh"; fi
source "$FORCED_PROFILE_FILE"
: "${FORCED_PROFILE:?}"; : "${FORCED_PROFILE_BIN:?}"; [[ -x "$FORCED_PROFILE_BIN" ]] || exit 3
source "$PROFILE_FILE"
: "${WARP_PROFILE:?}"; : "${ORBIT_PROFILE:?}"
ORBIT_PRECTX_COMPACT="${ORBIT_PRECTX_COMPACT:-0}"; ORBIT_PRECTX_FLAT_BID="${ORBIT_PRECTX_FLAT_BID:-0}"; ORBIT_PRECTX_FLAT_BID_FUSED="${ORBIT_PRECTX_FLAT_BID_FUSED:-0}"; ORBIT_PRECTX_WARPCOOP="${ORBIT_PRECTX_WARPCOOP:-0}"
ORBITCTA_FLAT="${ORBITCTA_FLAT:-0}"; ORBITCTA_FLAT_CHUNK="${ORBITCTA_FLAT_CHUNK:-1}"; ORBITCTA_FLAT_DYNAMIC="${ORBITCTA_FLAT_DYNAMIC:-0}"; ORBITCTA_FLAT_DYNAMIC_BATCH="${ORBITCTA_FLAT_DYNAMIC_BATCH:-1}"; ORBITCTA_FLAT_DYNAMIC_FUSE_LEASE_PREP="${ORBITCTA_FLAT_DYNAMIC_FUSE_LEASE_PREP:-0}"; ORBITCTA_FLAT_DYNAMIC_ADAPTIVE_WAVES="${ORBITCTA_FLAT_DYNAMIC_ADAPTIVE_WAVES:-0}"; ORBITCTA_FLAT_DYNAMIC_PIPE2="${ORBITCTA_FLAT_DYNAMIC_PIPE2:-0}"; ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_WARP="${ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_WARP:-0}"; ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_PRECTX_WARPCOOP="${ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_PRECTX_WARPCOOP:-0}"; ORBITCTA_FLAT_BLOCKS_PER_SM="${ORBITCTA_FLAT_BLOCKS_PER_SM:-0}"
ORBIT_QUAD_MLP="${ORBIT_QUAD_MLP:-0}"; ORBIT_QUAD_OVERLAP_LOCAL="${ORBIT_QUAD_OVERLAP_LOCAL:-0}"; ORBIT_QUAD_LOCAL_DIRECT_MAX="${ORBIT_QUAD_LOCAL_DIRECT_MAX:-0}"; ORBIT_QUAD_SPARSE_DESC_MLP="${ORBIT_QUAD_SPARSE_DESC_MLP:-0}"; ORBIT_QUAD_OVERLAP_BYPASS_LOCAL0="${ORBIT_QUAD_OVERLAP_BYPASS_LOCAL0:-0}"; ORBIT_QUAD_CPASYNC_PREFETCH_BYTES="${ORBIT_QUAD_CPASYNC_PREFETCH_BYTES:-0}"; ORBIT_QUAD_CPASYNC_GROUP_COLS="${ORBIT_QUAD_CPASYNC_GROUP_COLS:-1}"
ORBIT_PRECTX_FORWARD="${ORBIT_PRECTX_FORWARD:-0}"; ORBIT_PRECTX_REVERSE="${ORBIT_PRECTX_REVERSE:-0}"
[[ "$WARP_PROFILE" =~ ^[A-Za-z0-9_.-]+$ && "$ORBIT_PROFILE" =~ ^[A-Za-z0-9_.-]+$ ]] || exit 3
for x in ORBIT_PRECTX_COMPACT ORBIT_PRECTX_FLAT_BID ORBIT_PRECTX_FLAT_BID_FUSED ORBIT_PRECTX_WARPCOOP ORBITCTA_FLAT ORBITCTA_FLAT_DYNAMIC ORBITCTA_FLAT_DYNAMIC_FUSE_LEASE_PREP ORBITCTA_FLAT_DYNAMIC_PIPE2 ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_WARP ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_PRECTX_WARPCOOP ORBIT_QUAD_MLP ORBIT_QUAD_OVERLAP_LOCAL ORBIT_QUAD_SPARSE_DESC_MLP ORBIT_QUAD_OVERLAP_BYPASS_LOCAL0 ORBIT_PRECTX_FORWARD ORBIT_PRECTX_REVERSE; do v="${!x}"; [[ "$v" == 0 || "$v" == 1 ]] || exit 3; done
case "$ORBITCTA_FLAT_DYNAMIC_BATCH" in 1|2|4|8|16);;*)exit 3;;esac
case "$ORBITCTA_FLAT_DYNAMIC_ADAPTIVE_WAVES" in 0|1|2|4);;*)exit 3;;esac
case "$ORBIT_QUAD_CPASYNC_PREFETCH_BYTES" in 0|64|128|256);;*)exit 3;;esac
case "$ORBIT_QUAD_CPASYNC_GROUP_COLS" in 1|2|4);;*)exit 3;;esac
case "$ORBITCTA_FLAT_CHUNK" in 1|2|4|8|16|32);;*)exit 3;;esac
[[ "$ORBITCTA_FLAT_BLOCKS_PER_SM" =~ ^[0-9]+$ ]] || exit 3
[[ "$ORBIT_QUAD_LOCAL_DIRECT_MAX" =~ ^[0-9]+$ ]] && (( ORBIT_QUAD_LOCAL_DIRECT_MAX <= 8 )) || exit 3
[[ "$ORBITCTA_FLAT" == 1 || "$ORBITCTA_FLAT_CHUNK" == 1 ]] || exit 3
if [[ "$ORBITCTA_FLAT_DYNAMIC" == 1 ]]; then
  [[ "$ORBITCTA_FLAT" == 1 && "$ORBITCTA_FLAT_CHUNK" == 1 && "$ORBIT_PRECTX_WARPCOOP" == 0 ]] || exit 3
  (( ORBITCTA_FLAT_DYNAMIC_ADAPTIVE_WAVES == 0 || ORBITCTA_FLAT_DYNAMIC_BATCH > 1 )) || exit 3
  [[ "$ORBITCTA_FLAT_DYNAMIC_PIPE2" == 0 || "$ORBITCTA_FLAT_DYNAMIC_FUSE_LEASE_PREP" == 0 ]] || exit 3
  [[ "$ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_WARP" == 0 || "$ORBITCTA_FLAT_DYNAMIC_PIPE2" == 1 ]] || exit 3
  if [[ "$ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_PRECTX_WARPCOOP" == 1 ]]; then
    [[ "$ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_WARP" == 1 && "$ORBIT_PRECTX_FORWARD" == 1 && "$ORBIT_PRECTX_REVERSE" == 1 && "$ORBIT_PRECTX_COMPACT" == 1 && "$ORBIT_PRECTX_FLAT_BID_FUSED" == 0 ]] || exit 3
  fi
else
  [[ "$ORBITCTA_FLAT_DYNAMIC_BATCH" == 1 && "$ORBITCTA_FLAT_DYNAMIC_FUSE_LEASE_PREP" == 0 && "$ORBITCTA_FLAT_DYNAMIC_ADAPTIVE_WAVES" == 0 && "$ORBITCTA_FLAT_DYNAMIC_PIPE2" == 0 && "$ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_WARP" == 0 && "$ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_PRECTX_WARPCOOP" == 0 ]] || exit 3
fi
if [[ "$ORBIT_PRECTX_FLAT_BID" == 1 ]]; then
  [[ "$ORBITCTA_FLAT" == 1 && "$ORBITCTA_FLAT_CHUNK" == 1 && "$ORBIT_PRECTX_COMPACT" == 1 && "$ORBIT_PRECTX_FORWARD" == 1 && "$ORBIT_PRECTX_REVERSE" == 1 && "$ORBIT_PRECTX_WARPCOOP" == 0 ]] || exit 3
  [[ "$ORBITCTA_FLAT_DYNAMIC" == 1 || "$ORBIT_QUAD_MLP" == 0 ]] || exit 3
else
  [[ "$ORBIT_PRECTX_FLAT_BID_FUSED" == 0 ]] || exit 3
fi
if [[ "$ORBIT_PRECTX_WARPCOOP" == 1 ]]; then [[ "$ORBITCTA_FLAT" == 1 ]] && (( ORBITCTA_FLAT_CHUNK > 1 )) && [[ "$ORBIT_PRECTX_COMPACT" == 1 && "$ORBIT_PRECTX_FORWARD" == 1 && "$ORBIT_PRECTX_REVERSE" == 1 && "$ORBIT_PRECTX_FLAT_BID" == 0 && "$ORBITCTA_FLAT_DYNAMIC" == 0 ]] || exit 3; fi
if [[ "$ORBIT_QUAD_MLP" == 1 ]]; then
  [[ "$ORBITCTA_FLAT" == 1 ]] || exit 3
  [[ "${ORBIT_COL_ILP:-0}" == 4 ]] || exit 3
  if [[ "$ORBITCTA_FLAT_DYNAMIC" == 1 ]]; then
    [[ "$ORBITCTA_FLAT_CHUNK" == 1 && "$ORBIT_QUAD_OVERLAP_LOCAL" == 0 ]] || exit 3
    (( ORBIT_QUAD_LOCAL_DIRECT_MAX == 0 )) || exit 3
    [[ "$ORBIT_QUAD_SPARSE_DESC_MLP" == 0 && "$ORBIT_QUAD_OVERLAP_BYPASS_LOCAL0" == 0 && "$ORBIT_QUAD_CPASYNC_PREFETCH_BYTES" == 0 && "$ORBIT_QUAD_CPASYNC_GROUP_COLS" == 1 ]] || exit 3
  else
    (( ORBITCTA_FLAT_CHUNK > 1 )) || exit 3
    [[ "$ORBIT_PRECTX_FLAT_BID" == 0 && "$ORBIT_PRECTX_FLAT_BID_FUSED" == 0 ]] || exit 3
  fi
else
  [[ "$ORBIT_QUAD_OVERLAP_LOCAL" == 0 ]] && (( ORBIT_QUAD_LOCAL_DIRECT_MAX == 0 )) && [[ "$ORBIT_QUAD_SPARSE_DESC_MLP" == 0 && "$ORBIT_QUAD_OVERLAP_BYPASS_LOCAL0" == 0 && "$ORBIT_QUAD_CPASYNC_PREFETCH_BYTES" == 0 && "$ORBIT_QUAD_CPASYNC_GROUP_COLS" == 1 ]] || exit 3
fi

FORCED_FIXED="$ONEESAN_BUILD_DIR/b300_profiled_forced_n27"
WARP_FIXED="$ONEESAN_BUILD_DIR/b300_profiled_warp_${WARP_PROFILE}_n27"
ORBIT_FIXED="$ONEESAN_BUILD_DIR/b300_profiled_orbit_${ORBIT_PROFILE}_flat${ORBITCTA_FLAT}_chunk${ORBITCTA_FLAT_CHUNK}_dyn${ORBITCTA_FLAT_DYNAMIC}_db${ORBITCTA_FLAT_DYNAMIC_BATCH}_df${ORBITCTA_FLAT_DYNAMIC_FUSE_LEASE_PREP}_daw${ORBITCTA_FLAT_DYNAMIC_ADAPTIVE_WAVES}_dp${ORBITCTA_FLAT_DYNAMIC_PIPE2}_dpw${ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_WARP}_ppw${ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_PRECTX_WARPCOOP}_psm${ORBITCTA_FLAT_BLOCKS_PER_SM}_bid${ORBIT_PRECTX_FLAT_BID}_bf${ORBIT_PRECTX_FLAT_BID_FUSED}_wc${ORBIT_PRECTX_WARPCOOP}_quad${ORBIT_QUAD_MLP}_qol${ORBIT_QUAD_OVERLAP_LOCAL}_qld${ORBIT_QUAD_LOCAL_DIRECT_MAX}_qsd${ORBIT_QUAD_SPARSE_DESC_MLP}_ql0${ORBIT_QUAD_OVERLAP_BYPASS_LOCAL0}_qgc${ORBIT_QUAD_CPASYNC_GROUP_COLS}_qpf${ORBIT_QUAD_CPASYNC_PREFETCH_BYTES}_n27"
if [[ "$REBUILD_BUCKETS" == 1 ]]; then rm -f "$WARP_FIXED" "$ORBIT_FIXED"; fi
ln -sfn "$FORCED_PROFILE_BIN" "$FORCED_FIXED"
export PROFILE_FILE REBUILD=0
export PREFIX="${FINAL_PREFIX:-$ONEESAN_ROOT/work/b300_exact_hbm_profiled_staged_n27}"
echo "profiled staged forced=$FORCED_PROFILE bin=$FORCED_PROFILE_BIN warp=$WARP_PROFILE orbit=$ORBIT_PROFILE flat=$ORBITCTA_FLAT chunk=$ORBITCTA_FLAT_CHUNK dynamic=$ORBITCTA_FLAT_DYNAMIC dynamic_batch=$ORBITCTA_FLAT_DYNAMIC_BATCH dynamic_fuse_lease_prep=$ORBITCTA_FLAT_DYNAMIC_FUSE_LEASE_PREP dynamic_adaptive_waves=$ORBITCTA_FLAT_DYNAMIC_ADAPTIVE_WAVES dynamic_pipe2=$ORBITCTA_FLAT_DYNAMIC_PIPE2 dynamic_pipe2_producer_warp=$ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_WARP dynamic_pipe2_producer_prectx_warpcoop=$ORBITCTA_FLAT_DYNAMIC_PIPE2_PRODUCER_PRECTX_WARPCOOP flat_blocks_per_sm=$ORBITCTA_FLAT_BLOCKS_PER_SM bid=$ORBIT_PRECTX_FLAT_BID bid_fused=$ORBIT_PRECTX_FLAT_BID_FUSED warpcoop=$ORBIT_PRECTX_WARPCOOP quad=$ORBIT_QUAD_MLP" >&2
exec "$ONEESAN_ROOT/scripts/run/b300x8-exact-auto-hbm-profiled.sh" 27 "$@"
